```javascript
/**
 * @param {Array} arr
 * @param {Function} fn
 * @return {Array}
 */
var sortBy = function(arr, fn) {
    // JS sort takes a comparator, not a key function, so compare fn outputs.
    // Subtraction is safe: keys are unique numbers, and the result is negative,
    // zero or positive as sort expects.
    return arr.sort((a, b) => fn(a) - fn(b));
};
